<script>
document.querySelectorAll('[data-confirm-workflow]').forEach(function(form){form.addEventListener('submit',function(event){var status=form.querySelector('input[name="status"]:checked');if(!status)return;var message=status.value==='returned_for_correction'?'Return this step for correction? The reason will be preserved in case history.':status.value==='completed'?'Confirm that all requirements are complete?':'Save this workflow update?';if(!window.confirm(message))event.preventDefault();});});
</script>
